function QuickProfitCalculator(){
  const [buy,setBuy]=useState(""),[sell,setSell]=useState(""),[qty,setQty]=useState("10000"),[limit,setLimit]=useState("10000");
  const buyPrice=parseGp(buy)||0,sellPrice=parseGp(sell)||0,quantity=Math.max(0,Number(qty)||0),geLimit=Math.max(0,Number(limit)||0);
  const taxPer=taxFor(sellPrice),profitPer=sellPrice-buyPrice-taxPer,totalBuy=buyPrice*quantity,totalSell=sellPrice*quantity,totalTax=taxPer*quantity,totalProfit=profitPer*quantity,limitProfit=profitPer*geLimit,roi=buyPrice?profitPer/buyPrice*100:0;
  return <div className="quickCalcPopover" onPointerDown={e=>e.stopPropagation()}><div className="quickCalcHead"><div><strong>Quick profit calculator</strong><small>No item search needed · includes GE tax</small></div><CalculatorIcon size={16}/></div><div className="quickCalcFields"><label>Buy price<input inputMode="decimal" value={buy} onChange={e=>setBuy(e.target.value)} placeholder="1,000 or 1k"/></label><label>Sell price<input inputMode="decimal" value={sell} onChange={e=>setSell(e.target.value)} placeholder="1,200 or 1.2k"/></label><label>Quantity<input inputMode="numeric" type="number" min="0" value={qty} onChange={e=>setQty(e.target.value)} placeholder="10,000"/></label><label>GE limit<input inputMode="numeric" type="number" min="0" value={limit} onChange={e=>setLimit(e.target.value)} placeholder="10,000"/></label></div><div className="quickCalcResult"><div><span>Profit / 1</span><strong className={profitPer>=0?"green":"redtxt"}>{money(profitPer)}</strong></div><div><span>Total profit</span><strong className={totalProfit>=0?"green":"redtxt"}>{money(totalProfit)}</strong></div><div><span>Total invested</span><b>{money(totalBuy)}</b></div><div><span>Total GE tax</span><b>{money(totalTax)}</b></div><div><span>Sell total</span><b>{money(totalSell)}</b></div><div><span>ROI</span><b>{buyPrice&&sellPrice?pct(roi):"—"}</b></div><div className="quickCalcResultWide"><span>Full GE limit profit</span><strong className={limitProfit>=0?"green":"redtxt"}>{money(limitProfit)}</strong><small>{num(geLimit)} units after GE tax</small></div></div><small className="quickCalcNote">Example: buy 1,000 × 10,000 and sell 1,200 × 10,000 calculates the per-item and full trade profit automatically.</small></div>
}

function NotificationPopover({alerts,clear,openItem,close}){
  return <div className="notificationPopover" role="dialog" aria-label="Notifications" onClick={e=>e.stopPropagation()}>
    <div className="popoverHead"><strong>Notifications</strong><button onClick={close} aria-label="Close notifications"><X size={15}/></button></div>
    <div className="popoverList">
      {alerts.length ? alerts.slice(0,12).map(a=><button key={a.id} onClick={()=>{openItem(a.itemId);close()}}>
        <Bell size={15}/><div><strong>{a.name}</strong><small>{a.metric} hit {num(a.target)}{a.metric==="roi"?"%":" gp"} · {new Date(a.at).toLocaleString("en-GB")}</small></div><ChevronRight size={14}/>
      </button>) : <div className="popoverEmpty"><Bell size={15}/> No notifications yet.</div>}
    </div>
    {alerts.length>0&&<button className="clearPopover" onClick={clear}>Clear notifications</button>}
  </div>
}

function RuleModal({items,existing,onClose,onSave}){
 const [q,setQ]=useState(existing?.name||"");
 const [id,setId]=useState(existing?.itemId||existing?.id||items[0]?.id);
 const [metric,setMetric]=useState(existing?.metric||"sell");
 const [direction,setDirection]=useState(existing?.direction||"above");
 const [value,setValue]=useState(existing?.value!=null?String(existing.value):"100000");
 closeOnEscape(onClose);
 const found=fuzzyItems(items,q,7);
 const isPct=metric==="roi";
 const save=()=>{const x=items.find(x=>x.id===Number(id)||x.id===id);const parsed=isPct?Number(String(value).replace(/,/g,"")):parseGp(value);if(!x||!Number.isFinite(parsed)||parsed<=0)return;onSave({id:existing?.id||crypto.randomUUID(),name:x.name,itemId:x.id,metric,direction,value:parsed})};
 const label={sell:"Sell price",buy:"Buy price",margin:"After-tax margin",roi:"ROI",volume:"24h volume",flipScore:"Flip Score",riskScore:"Risk score",potentialProfit:"Potential profit"}[metric]||metric;
 return <div className="modalback alertModalBack" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}} onClick={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal alertRuleModal" onMouseDown={e=>e.stopPropagation()} onPointerDownCapture={e=>e.stopPropagation()} onClick={e=>e.stopPropagation()}><button className="close" type="button" onClick={onClose}><X/></button><div className="eyebrow">{existing?"EDIT ALERT":"NEW ALERT"}</div><h2>{existing?"Tune the trigger.":"Build an intelligent alert."}</h2><p className="alertModalLead">Track price, margin, ROI, liquidity, score or capital opportunity. The rule arms again after the condition clears.</p><label>Item</label><input value={q} onChange={e=>{setQ(e.target.value);const f=fuzzyItems(items,e.target.value,1)[0];if(f)setId(f.id)}} placeholder="Search item…" autoComplete="off"/>{q&&<div className="suggest">{found.map(x=><button type="button" key={x.id} onMouseDown={e=>e.preventDefault()} onClick={()=>{setId(x.id);setQ(x.name)}}>{x.name}</button>)}</div>}<div className="twocol"><div><label>Metric</label><select value={metric} onChange={e=>setMetric(e.target.value)}><option value="sell">Sell price</option><option value="buy">Buy price</option><option value="margin">After-tax margin</option><option value="roi">ROI</option><option value="volume">24h volume</option><option value="flipScore">Flip Score</option><option value="riskScore">Risk score</option><option value="potentialProfit">Potential profit</option></select></div><div><label>Condition</label><select value={direction} onChange={e=>setDirection(e.target.value)}><option value="above">rises above</option><option value="below">drops below</option></select></div></div><label>Threshold <small className="inputHint">{label} · select, replace, or type freely</small></label><input className="thresholdInput" value={value} onChange={e=>setValue(e.target.value)} onFocus={e=>e.stopPropagation()} onMouseDown={e=>e.stopPropagation()} onPointerDown={e=>e.stopPropagation()} placeholder={isPct?"2.5":"100k, 2.5m…"} inputMode="decimal" autoComplete="off"/><div className="alertRulePreview"><Bell size={14}/><span>You’ll be alerted when <b>{q||"this item"}</b> {direction} <b>{isPct?`${Number(value||0).toFixed(2)}%`:metric.includes("Score")?Number(value||0):money(parseGp(value)||0)}</b>.</span></div><button className="primary wide" type="button" onClick={save}>{existing?"Save changes":"Create alert"}</button></div></div>}

