    {contextMenu&&<ItemContextMenu item={contextMenu.item} x={contextMenu.x} y={contextMenu.y} onClose={()=>setContextMenu(null)} onOpen={()=>selectItem(contextMenu.item,"24h",fullAnalyticsForViewport()?"full":"drawer")} onWatch={()=>toggleWatch(contextMenu.item.id)} onAlert={()=>{setEditRule({id:crypto.randomUUID(),name:contextMenu.item.name,itemId:contextMenu.item.id,metric:"sell",direction:"above",value:contextMenu.item.sell||0});setRuleModal(true)}} onGe={()=>addToGe(contextMenu.item)}/>}
    {ruleModal&&<RuleModal items={items} existing={editRule} onClose={()=>{setRuleModal(false);setEditRule(null)}} onSave={rule=>{const next=editRule?alertRulesRef.current.map(r=>r.id===editRule.id?{...r,...rule,lastTriggered:r.lastTriggered||0,armed:true}:r):[...alertRulesRef.current,{...rule,lastTriggered:0,armed:true}];alertRulesRef.current=next;setAlertRules(next);localStorage.setItem("osrsflipit-rules",JSON.stringify(next));setRuleModal(false);setEditRule(null)}}/>}
