 useEffect(()=>{localStorage.setItem("osrshub-loadout",JSON.stringify(loadout))},[loadout]);useEffect(()=>{localStorage.setItem("osrshub-loadout-details",JSON.stringify(details))},[details]);useEffect(()=>{localStorage.setItem("osrshub-loadout-builds",JSON.stringify(savedBuilds.slice(0,12)))},[savedBuilds]);
