 const slotMatches=(x,slot)=>{const raw=x?.slot||x?.equipment_slot||x?.equipment?.slot||x?.equipment?.equipment_slot;const text=Array.isArray(raw)?raw.join(" ").toLowerCase():String(raw||"").toLowerCase();return !text||text.includes(slot)||((slot==="hands"||slot==="feet")&&text.includes(slot==="hands"?"glove":"boot"))};
