 const upgradePreview=slots.map(slot=>{const current=details[slot]?.equipment||details[slot]||{};const currentScore=style==="melee"?Number(current.attack_slash||0)+2*Number(current.melee_strength||0):style==="ranged"?Number(current.attack_ranged||0)+2*Number(current.ranged_strength||0):Number(current.attack_magic||0)+2*Number(current.magic_damage||0);const candidatesFor=slotData[slot]||[];const best=candidatesFor.filter(x=>!equippedIds.has(Number(x.id))).map(x=>{const e=x.equipment||{};const score=style==="melee"?Number(e.attack_slash||0)+2*Number(e.melee_strength||0):style==="ranged"?Number(e.attack_ranged||0)+2*Number(e.ranged_strength||0):Number(e.attack_magic||0)+2*Number(e.magic_damage||0);return {...x,score,gain:score-currentScore}}).filter(x=>x.gain>0).sort((a,b)=>b.gain-a.gain)[0];return {slot,best,currentScore}}).filter(x=>x.best).sort((a,b)=>b.best.gain-a.best.gain).slice(0,6);
